// C++20 Zero-overhead RAII & Type Safety vs C Raw Allocation
#include <iostream>
#include <memory>
#include <span>
#include <concepts>

// 1. C-style: Thiếu type safety, dễ quên giải phóng, không constructor
// struct Order { int id; double price; };
// Order* o = (Order*)malloc(sizeof(Order)); free(o);

// 2. Modern C++20 style: Type-safe, Zero-overhead RAII, Compile-time validation
template<typename T>
concept NumericPrice = std::floating_point<T> || std::integral<T>;

template<NumericPrice T>
class LimitOrder {
private:
    uint64_t id_;
    T price_;
public:
    constexpr LimitOrder(uint64_t id, T price) noexcept : id_(id), price_(price) {}
    [[nodiscard]] constexpr T getPrice() const noexcept { return price_; }
    [[nodiscard]] constexpr uint64_t getId() const noexcept { return id_; }
};

int main() {
    // Tự động giải phóng khi ra khỏi scope, không tốn runtime overhead so với stack C
    auto order = std::make_unique<LimitOrder<double>>(1001, 142.50);
    std::cout << "Order ID: " << order->getId() << " Price: " << order->getPrice() << '\n';
    return 0;
}

