class NetworkPacket {
private:
    uint32_t seq_;
public:
    NetworkPacket(uint32_t s) : seq_(s) {
        std::cout << "Packet " << seq_ << " constructed\n";
    }
    ~NetworkPacket() {
        std::cout << "Packet " << seq_ << " destructed\n";
    }
    uint32_t seq() const noexcept { return seq_; }
};

int main() {
    // 1. C-style malloc: Chỉ cấp phát raw bytes, KHÔNG gọi constructor
    void* raw_mem = std::malloc(sizeof(NetworkPacket));
    if (!raw_mem) return 1;

    // 2. Placement new: Khởi tạo đối tượng ngay trên buffer có sẵn
    NetworkPacket* pkt = new (raw_mem) NetworkPacket(42);

    // Bắt buộc gọi destructor thủ công khi dùng placement new
    pkt->~NetworkPacket();
    std::free(raw_mem);

    // 3. Regular new: Cấp phát + gọi Constructor an toàn kiểu
    NetworkPacket* standard_pkt = new NetworkPacket(100);
    delete standard_pkt; // Gọi Destructor + operator delete
    return 0;
}

