};

// Hàm xử lý âm thanh trong Real-time Audio Loop: Cấp phát 100% trên Stack
void processAudioRealtime() {
    // Stack allocation: O(1) pointer decrement, cache-friendly
    std::array<AudioSample, 128> buffer{};
    for (size_t i = 0; i < buffer.size(); ++i) {
        buffer[i].left = 0.5f;
        buffer[i].right = 0.5f;
