#if defined(__GNUC__) || defined(__clang__)
[[gnu::always_inline]] inline uint16_t extractFlag(uint64_t rawHeader) noexcept {
    return static_cast<uint16_t>(rawHeader & 0xFFFF);
}
#else
inline uint16_t extractFlag(uint64_t rawHeader) noexcept {
    return static_cast<uint16_t>(rawHeader & 0xFFFF);
}
#endif

