#include <iostream>

class Vector3D {
public:
    float x, y, z;
    constexpr Vector3D(float x_ = 0, float y_ = 0, float z_ = 0) noexcept : x(x_), y(y_), z(z_) {}

    // Operator Overloading: Phép cộng 2 vector
    [[nodiscard]] constexpr Vector3D operator+(const Vector3D& other) const noexcept {
        return Vector3D(x + other.x, y + other.y, z + other.z);
    }

    // Function Overloading: Nhân vector với một số thực vô hướng
    [[nodiscard]] constexpr Vector3D scale(float factor) const noexcept {
        return Vector3D(x * factor, y * factor, z * factor);
    }

    // Overload: Nhân vector với các hệ số không đồng nhất trên từng trục
    [[nodiscard]] constexpr Vector3D scale(float fx, float fy, float fz) const noexcept {
        return Vector3D(x * fx, y * fy, z * fz);
    }
};

int main() {
    Vector3D v1{1.0f, 2.0f, 3.0f};
    Vector3D v2{4.0f, 5.0f, 6.0f};

    Vector3D sum = v1 + v2;       // Sử dụng operator+
    Vector3D scaled = sum.scale(2.0f); // Sử dụng overloaded scale

    std::cout << "Result: (" << scaled.x << ", " << scaled.y << ", " << scaled.z << ")\n";
    return 0;
}

