void safeApproach() {
    std::weak_ptr<int> observer;
    {
        auto sharedResource = std::make_shared<int>(42);
        observer = sharedResource; // Quan sát nhưng không tăng strong ref count

        if (auto locked = observer.lock()) {
            std::cout << "Resource is alive: " << *locked << '\n';
