int main() {
    // Container: std::vector lưu trữ mảng liên tục trên Heap
    std::vector<int> sensorReadings = {45, 12, 85, 32, 89, 21, 67};

    // Algorithm kết hợp Iterators: Sắp xếp tại chỗ O(N log N)
    std::sort(sensorReadings.begin(), sensorReadings.end());

    // Functor / Lambda kết hợp Algorithm: std::transform để lọc nhiễu
    std::vector<int> calibrated;
    calibrated.resize(sensorReadings.size());
    std::transform(sensorReadings.begin(), sensorReadings.end(), calibrated.begin(),
                   [](int raw) noexcept { return raw + 5; });

    // Algorithm tính tổng: std::accumulate
    long long total = std::accumulate(calibrated.begin(), calibrated.end(), 0LL);

    std::cout << "Average calibrated reading: " << (total / calibrated.size()) << '\n';
    return 0;
}

