// Custom RAII Wrapper cho File Descriptor (POSIX C-style resource)
class ScopedFileDescriptor {
private:
    FILE* file_;
public:
    explicit ScopedFileDescriptor(const char* path, const char* mode) {
        file_ = std::fopen(path, mode);
        if (!file_) throw std::runtime_error("Failed to open file!");
        std::cout << "File resource acquired\n";
    }

    ~ScopedFileDescriptor() noexcept {
        if (file_) {
            std::fclose(file_);
            std::cout << "File resource released automatically by RAII\n";
        }
    }

    // Ngăn chặn copy để tránh double close (Move-only)
    ScopedFileDescriptor(const ScopedFileDescriptor&) = delete;
    ScopedFileDescriptor& operator=(const ScopedFileDescriptor&) = delete;
};

std::mutex g_dataMutex;

void processOrderBook() {
    // std::lock_guard là RAII wrapper cho Mutex lock
    std::lock_guard<std::mutex> lock(g_dataMutex);
    std::cout << "Mutex locked\n";

    ScopedFileDescriptor logFile("log.txt", "w");

    // Giả sử có lỗi xảy ra hoặc early return
    bool simulateError = true;
    if (simulateError) {
        std::cout << "Early exit due to condition\n";
        return; // RAII đảm bảo file được close và mutex được unlock TỨC THÌ
    }
}

