struct Node {
    int id;
    std::shared_ptr<Node> next; // Shared ownership
    std::weak_ptr<Node> prev;   // Weak reference: Tránh circular reference gây leak

    Node(int val) : id(val) { std::cout << "Node " << id << " created\n"; }
    ~Node() { std::cout << "Node " << id << " destroyed\n"; }
};

int main() {
    // 1. unique_ptr: Zero overhead, exclusive ownership
    auto uPtr = std::make_unique<int>(100);
    // auto uCopy = uPtr; // LỖI BIÊN DỊCH: Không cho phép copy
    auto uMoved = std::move(uPtr); // Chuyển giao quyền sở hữu qua move

    // 2. shared_ptr & weak_ptr phá vỡ liên kết vòng
    auto nodeA = std::make_shared<Node>(1);
    auto nodeB = std::make_shared<Node>(2);

    nodeA->next = nodeB; // A trỏ tới B (B strong count = 2)
    nodeB->prev = nodeA; // B trỏ yếu về A (A strong count vẫn là 1, không tăng)

    // Khi nodeA và nodeB ra khỏi scope, cả hai đều được hủy hoàn toàn!
