class DataBuffer {
private:
    size_t size_;
    char* data_;
public:
    DataBuffer(const char* str) : size_(std::strlen(str)) {
        data_ = new char[size_ + 1];
        std::memcpy(data_, str, size_ + 1);
    }

    // Destructor
    ~DataBuffer() {
        delete[] data_;
    }

    // 1. Deep Copy Constructor: Cấp phát mới và clone dữ liệu
    DataBuffer(const DataBuffer& other) : size_(other.size_) {
        data_ = new char[size_ + 1];
        std::memcpy(data_, other.data_, size_ + 1);
        std::cout << "Deep copy executed!\n";
    }

    // 2. Copy Assignment Operator sử dụng Copy-and-Swap idiom an toàn exception
    DataBuffer& operator=(DataBuffer other) noexcept {
        std::swap(size_, other.size_);
        std::swap(data_, other.data_);
        return *this;
    }
};

int main() {
    DataBuffer buf1("Financial_Market_Data");
    DataBuffer buf2 = buf1; // Kích hoạt Deep Copy: buf1 và buf2 có 2 buffer heap độc lập
    return 0; // Cả 2 được hủy an toàn mà không bị Double-Free
}

