#include <unordered_map>
#include <string>

int main() {
    // 1. std::map: Luôn duy trì thứ tự đã sắp xếp (O(log N))
    std::map<int, std::string> orderBookByPrice;
    orderBookByPrice[105] = "Sell Order B";
    orderBookByPrice[100] = "Buy Order A";
    orderBookByPrice[102] = "Order C";

    std::cout << "=== std::map (Sorted by Price) ===\n";
    for (const auto& [price, desc] : orderBookByPrice) {
        std::cout << price << " -> " << desc << '\n'; // Tự động in: 100, 102, 105
    }

    // 2. std::unordered_map: Bảng băm không có thứ tự (O(1) average lookup)
    std::unordered_map<std::string, uint64_t> userSessions;
    userSessions["session_xyz"] = 998811;
    userSessions["session_abc"] = 112233;

    std::cout << "=== std::unordered_map (O(1) Direct Lookup) ===\n";
    auto it = userSessions.find("session_xyz");
    if (it != userSessions.end()) {
        std::cout << "User ID: " << it->second << '\n';
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <list>
#include <iterator>

int main() {
    // 1. Random Access & Contiguous Iterator (std::vector)
    std::vector<int> vec = {10, 20, 30, 40, 50};
    auto vecIt = vec.begin();
    vecIt += 3; // O(1) pointer arithmetic
    std::cout << "Vector index 3: " << *vecIt << '\n'; // In ra 40

    // 2. Bidirectional Iterator (std::list)
    std::list<int> lst = {10, 20, 30, 40, 50};
    auto lstIt = lst.begin();
    // lstIt += 3; // LỖI BIÊN DỊCH: list iterator không hỗ trợ Random Access!
    std::advance(lstIt, 3); // O(N) traversal từng node
    std::cout << "List index 3: " << *lstIt << '\n'; // In ra 40

    // Kiểm tra category tại compile-time
    static_assert(std::random_access_iterator<decltype(vec.begin())>);
    static_assert(!std::random_access_iterator<decltype(lst.begin())>);
    return 0;
}

#include <iostream>
#include <memory>
#include <functional>

int main() {
    int factor = 10;
    auto uPtr = std::make_unique<int>(100);

    // C++14 Generic Lambda kết hợp Move Capture và mutable
    auto processData = [factor, p = std::move(uPtr)](int val) mutable -> int {
        factor += 5; // Hợp lệ nhờ từ khóa mutable (chỉ thay đổi bản copy trong closure)
        return (val + *p) * factor;
    };

    std::cout << "Result: " << processData(2) << '\n'; // In ra (2 + 100) * 15 = 1530
    std::cout << "Factor gốc bên ngoài: " << factor << '\n'; // Vẫn là 10

    // std::cout << (uPtr == nullptr); // uPtr đã bị move vào trong lambda
    return 0;
}

