// NGUY CƠ RÒ RỈ: Vòng lặp tham chiếu cyclic reference
struct Node {
    std::shared_ptr<Node> next;
    // std::shared_ptr<Node> prev; // GÂY LEAK NẾU DÙNG shared_ptr!
    std::weak_ptr<Node> prev;      // GIẢI PHÁP: Dùng weak_ptr phá vỡ chu trình

    ~Node() { std::cout << "Node cleanly destructed\n"; }
};

void safeExecution() {
    // Sử dụng RAII triệt để: unique_ptr tự giải phóng khi ra khỏi scope
    auto resource = std::make_unique<uint8_t[]>(1024 * 1024); // 1MB buffer

    auto n1 = std::make_shared<Node>();
    auto n2 = std::make_shared<Node>();
    n1->next = n2;
    n2->prev = n1; // An toàn nhờ weak_ptr
} // Ra khỏi scope: Toàn bộ 1MB buffer và 2 Node đều được giải phóng 100%

int main() {
    safeExecution();
    std::cout << "Execution finished with zero leaks!\n";
    return 0;
}

