#include <iostream>
#include <atomic>

class ConnectionPool {
private:
    // inline static (C++17): Định nghĩa và khởi tạo trực tiếp trong header
    inline static std::atomic<uint32_t> activeConnections_{0};
    uint32_t connectionId_;
public:
    ConnectionPool() : connectionId_(++activeConnections_) {}
    ~ConnectionPool() { --activeConnections_; }

    // Static member function: Không có con trỏ this, gọi trực tiếp qua class
    static uint32_t getActiveCount() noexcept {
        return activeConnections_.load();
    }

    // Meyer's Singleton: Thread-safe từ C++11, tránh Static Initialization Order Fiasco
    static ConnectionPool& instance() {
        static ConnectionPool pool;
        return pool;
    }
};

int main() {
    std::cout << "Initial active: " << ConnectionPool::getActiveCount() << '\n';
    {
        ConnectionPool conn1;
        ConnectionPool conn2;
        std::cout << "Peak active: " << ConnectionPool::getActiveCount() << '\n'; // 2
    }
    std::cout << "After scope: " << ConnectionPool::getActiveCount() << '\n'; // 0
    return 0;
}

