int main() {
    std::vector<int> data = {42, 12, 88, 3, 27, 65, 9, 50};

    // 1. std::sort: Introsort O(N log N)
    std::sort(data.begin(), data.end());

    // 2. std::find: Tìm kiếm O(N) với predicate
    auto it = std::find(data.begin(), data.end(), 27);
    if (it != data.end()) {
        std::cout << "Found 27 at index: " << std::distance(data.begin(), it) << '\n';
    }

    // 3. std::transform: Nhân đôi mọi phần tử (Mapping)
    std::vector<int> doubled(data.size());
    std::transform(data.begin(), data.end(), doubled.begin(), [](int n) { return n * 2; });

    // 4. std::accumulate: Tính tổng toàn bộ mảng
    long long sum = std::accumulate(doubled.begin(), doubled.end(), 0LL);
    std::cout << "Sum of doubled elements: " << sum << '\n';

    return 0;
}

