        configs_["timeout_ms"] = "5000";
    }

    // Trả về std::optional: Rõ ràng, an toàn, zero heap allocation
    [[nodiscard]] std::optional<std::string> get(const std::string& key) const noexcept {
        auto it = configs_.find(key);
        if (it != configs_.end()) {
            return it->second; // Trả về có giá trị
