// Helper struct để tạo visitor nạp chồng lambda (C++17 Overload pattern)
template<class... Ts> struct Overloaded : Ts... { using Ts::operator()...; };
template<class... Ts> Overloaded(Ts...) -> Overloaded<Ts...>;

struct Heartbeat { uint64_t timestamp; };
struct OrderPlaced { uint64_t orderId; double price; };

using NetworkEvent = std::variant<Heartbeat, OrderPlaced, std::string>;

int main() {
    NetworkEvent event = OrderPlaced{1001, 150.25};

    // Pattern matching compile-time an toàn tuyệt đối với std::visit
    std::visit(Overloaded {
        [](const Heartbeat& h) {
            std::cout << "Heartbeat at: " << h.timestamp << '\n';
        },
        [](const OrderPlaced& o) {
            std::cout << "Order [" << o.orderId << "] placed at $" << o.price << '\n';
        },
        [](const std::string& err) {
            std::cout << "Network Error: " << err << '\n';
        }
    }, event);

    return 0;
}

