// Zero-copy parser: Nhận string_view qua pass-by-value
void parseHttpHeader(std::string_view header) {
    // Substring O(1): Chỉ dịch chuyển con trỏ và tính toán lại length, ZERO heap allocation!
    size_t colonPos = header.find(':');
    if (colonPos != std::string_view::npos) {
        std::string_view key = header.substr(0, colonPos);
        std::string_view value = header.substr(colonPos + 2);
        std::cout << "Key: [" << key << "] -> Value: [" << value << "]\n";
    }
}

int main() {
    // 1. Hoạt động trên String Literal (.rodata) - Zero allocation
    parseHttpHeader("Content-Type: application/json");

    // 2. Hoạt động trên std::string thông thường
    std::string dynamicHeader = "Authorization: Bearer token12345";
    parseHttpHeader(dynamicHeader);

    return 0;
}

