#include <iostream>
#include <queue>
#include <stack>
#include <vector>

struct RenderTask {
    int priority;
    std::string name;

    // Toán tử < quy định Max-Heap cho priority_queue
    bool operator<(const RenderTask& other) const noexcept {
        return priority < other.priority;
    }
};

int main() {
    // 1. std::stack (LIFO) dựa trên std::deque
    std::stack<int> s;
    s.push(10); s.push(20);
    std::cout << "Stack top: " << s.top() << '\n'; // 20
    s.pop();

    // 2. std::queue (FIFO) dựa trên std::deque
    std::queue<int> q;
    q.push(1); q.push(2);
    std::cout << "Queue front: " << q.front() << '\n'; // 1
    q.pop();

    // 3. std::priority_queue dựa trên std::vector (Binary Heap O(log N))
    std::priority_queue<RenderTask> taskQueue;
    taskQueue.push({10, "Render Background"});
    taskQueue.push({100, "Render Main Character (Urgent)"});
    taskQueue.push({50, "Apply Shaders"});

    // Luôn lấy ra task có priority cao nhất trước
    while (!taskQueue.empty()) {
        const auto& task = taskQueue.top();
        std::cout << "Executing [Priority " << task.priority << "]: " << task.name << '\n';
        taskQueue.pop();
    }
    return 0;
}

