// 1. Đa hình Compile-time qua C++20 Concepts (Zero runtime cost, full inlining)
template<typename T>
concept MatchingEngine = requires(T engine, int orderId) {
    { engine.match(orderId) } -> std::same_as<void>;
};

struct FastHftEngine {
    void match(int orderId) noexcept {
        std::cout << "Compile-time fast matching: " << orderId << '\n';
    }
};

template<MatchingEngine Engine>
