int main() {
    // Minh họa overhead bộ nhớ:
    std::cout << "Kích thước 1 node trong std::list<int>: " 
              << (sizeof(int) + 2 * sizeof(void*)) << " bytes (ít nhất 24 bytes cho 4 bytes data!)\n";
    std::cout << "Dung lượng 1 phần tử trong std::vector<int>: " 
              << sizeof(int) << " bytes (liên tục 100% không hao phí)\n";

    // Trường hợp DUY NHẤT cần dùng std::list: splice O(1) không tốn chi phí copy
    std::list<int> listA = {1, 2, 3};
    std::list<int> listB = {4, 5, 6};
    auto it = listA.begin();
    std::advance(it, 1); // Trỏ tới số 2

    // Ghép toàn bộ listB vào giữa listA: Chỉ đổi con trỏ node, O(1), không allocate lại
    listA.splice(it, listB);

    std::cout << "ListA sau splice: ";
    for (int n : listA) std::cout << n << ' '; // 1 4 5 6 2 3
    std::cout << '\n';
    return 0;
}

