// Chuẩn Rule of Five: Quản lý tài nguyên thô an toàn và tối ưu tuyệt đối
class RawSocketWrapper {
private:
    int fd_{-1};
public:
    explicit RawSocketWrapper(int fd) noexcept : fd_(fd) {}

    // 1. Destructor
    ~RawSocketWrapper() noexcept {
        if (fd_ != -1) { /* close(fd_); */ std::cout << "Socket " << fd_ << " closed\n"; }
    }

    // 2. Delete Copy Constructor (Socket là tài nguyên độc quyền, không copy)
    RawSocketWrapper(const RawSocketWrapper&) = delete;

    // 3. Delete Copy Assignment Operator
    RawSocketWrapper& operator=(const RawSocketWrapper&) = delete;

    // 4. Move Constructor: Chuyển giao quyền sở hữu file descriptor
    RawSocketWrapper(RawSocketWrapper&& other) noexcept : fd_(other.fd_) {
        other.fd_ = -1;
    }

    // 5. Move Assignment Operator
    RawSocketWrapper& operator=(RawSocketWrapper&& other) noexcept {
        if (this != &other) {
            if (fd_ != -1) { /* close(fd_); */ }
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }
};

int main() {
    RawSocketWrapper sock1(10);
    // RawSocketWrapper sock2 = sock1; // LỖI BIÊN DỊCH: Đã delete copy
    RawSocketWrapper sock3 = std::move(sock1); // Di chuyển an toàn qua Move Constructor
    return 0;
}

