// 1. Function Template với C++20 Concept ràng buộc kiểu số học
template<typename T>
requires std::integral<T> || std::floating_point<T>
[[nodiscard]] constexpr T calculateMidpoint(T a, T b) noexcept {
    return a + (b - a) / 2;
}

// 2. Class Template: Circular Buffer cố định dung lượng
template<typename T, size_t Capacity>
class RingBuffer {
private:
    T buffer_[Capacity];
    size_t head_{0};
public:
    void push(T val) noexcept {
        buffer_[head_ % Capacity] = std::move(val);
        ++head_;
    }
    [[nodiscard]] size_t capacity() const noexcept { return Capacity; }
};

int main() {
    // Function template tự động suy diễn kiểu T = double
    auto mid = calculateMidpoint(10.5, 20.5);
    std::cout << "Midpoint: " << mid << '\n';

    // Class template với non-type template parameter (size_t Capacity)
    RingBuffer<int, 128> queue;
    queue.push(42);
    std::cout << "Ring buffer capacity: " << queue.capacity() << '\n';
    return 0;
}

