// Tính toán bảng mã băm CRC32 hoàn toàn tại compile-time (C++14/20 constexpr)
constexpr auto generateCrc32Table() noexcept {
    std::array<uint32_t, 256> table{};
    for (uint32_t i = 0; i < 256; ++i) {
        uint32_t crc = i;
        for (uint32_t j = 0; j < 8; ++j) {
            crc = (crc & 1) ? ((crc >> 1) ^ 0xEDB88320U) : (crc >> 1);
        }
        table[i] = crc;
    }
    return table;
}

// Bảng lookup table được tính toán 100% tại compile-time và ghi thẳng vào phân vùng .rodata
constexpr auto g_crcTable = generateCrc32Table();

int main() {
    // Kiểm tra compile-time: Giá trị đã có sẵn mà không tốn 1 chu kỳ CPU runtime nào!
    static_assert(g_crcTable[1] == 0x77073096U, "Compile-time CRC mismatch!");

    std::cout << "CRC Table entry [1]: 0x" << std::hex << g_crcTable[1] << '\n';
    return 0;
}

