    HeavyPayload(const HeavyPayload&) { std::cout << "Copied (Lvalue)\n"; }
    HeavyPayload(HeavyPayload&&) noexcept { std::cout << "Moved (Rvalue)\n"; }
};

void consume(const HeavyPayload& p) { std::cout << "consume(const HeavyPayload&)\n"; }
void consume(HeavyPayload&& p)      { std::cout << "consume(HeavyPayload&&)\n"; }

// Factory hàm triển khai Perfect Forwarding chuẩn Modern C++
template<typename T, typename Arg>
std::unique_ptr<T> createWrapper(Arg&& arg) {
    // std::forward bảo toàn hoàn hảo value category của arg ban đầu
    return std::make_unique<T>(std::forward<Arg>(arg));
}

