    // arg được suy luận là HeavyPayload& -> std::forward trả về lvalue
    consume(std::forward<HeavyPayload&>(p)); // Gọi bản copy

    std::cout << "--- Passing Rvalue via std::move ---\n";
    // std::move ép kiểu vô điều kiện thành rvalue -> Kích hoạt move
    consume(std::move(p)); // Gọi bản move

