class BankAccount {
public:
    mutable std::mutex mtx;
    int balance{1000};
};

// Chuyển tiền an toàn tuyệt đối chống Deadlock với std::scoped_lock (C++17)
void transferMoney(BankAccount& from, BankAccount& to, int amount) {
    // std::scoped_lock khóa đồng thời nhiều mutex bằng thuật toán tránh deadlock
    std::scoped_lock lock(from.mtx, to.mtx);

    if (from.balance >= amount) {
        from.balance -= amount;
        to.balance += amount;
        std::cout << "Transferred " << amount << " successfully\n";
    }
} // Tự động mở khóa cả 2 mutex khi ra khỏi scope theo RAII

int main() {
    BankAccount acc1;
    BankAccount acc2;

    // Tạo 2 luồng chuyển tiền chéo nhau đồng thời
    std::thread t1(transferMoney, std::ref(acc1), std::ref(acc2), 200);
    std::thread t2(transferMoney, std::ref(acc2), std::ref(acc1), 100);

    // Bắt buộc phải join() trước khi thread object bị hủy
    t1.join();
    t2.join();

    std::cout << "Acc1 balance: " << acc1.balance << " | Acc2 balance: " << acc2.balance << '\n';
    return 0;
}

